-- WAEC Question Bank: all BECE & WASSCE subjects × years 2010–2025
-- Generated by scripts/generate-waec-question-bank.mjs
-- Run after apply-waec-platform.sql

CREATE TABLE IF NOT EXISTS public.waec_exam_years (
  level text NOT NULL CHECK (level IN ('bece', 'wassce')),
  year int NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  PRIMARY KEY (level, year)
);

