CREATE OR REPLACE FUNCTION public.get_waec_question_catalog(p_level text DEFAULT NULL)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.sort_order, t.subject_name), '[]'::jsonb)
  FROM (
    SELECT
      s.id AS subject_id,
      s.name AS subject_name,
      s.level,
      s.category,
      s.sort_order,
      COUNT(q.id)::int AS total_questions,
      (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
          'year', y.year,
          'question_count', y.cnt,
          'paper_types', y.papers
        ) ORDER BY y.year DESC), '[]'::jsonb)
        FROM (
          SELECT q2.year, COUNT(*)::int AS cnt, jsonb_agg(DISTINCT q2.paper_type) AS papers
          FROM public.waec_questions q2
          WHERE q2.subject_id = s.id AND q2.is_active = true
          GROUP BY q2.year
        ) y
      ) AS years
    FROM public.waec_subjects s
    LEFT JOIN public.waec_questions q ON q.subject_id = s.id AND q.is_active = true
    WHERE s.is_active = true AND (p_level IS NULL OR s.level = p_level)
    GROUP BY s.id, s.name, s.level, s.category, s.sort_order
  ) t;
$$;

